values ('10000000-0000-4000-8000-000000000026'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Feijoada brésilienne','feijoada-bresilienne','Ragoût brésilien de haricots noirs mijotés avec bacon, porc et saucisse, ail, oignons et laurier.','Haricots noirs mijotés longuement avec plusieurs morceaux de porc.','fr','BR','Brésil','Ragoût','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'medium'::public.recipe_difficulty,25,150,10.00,now(),(select id from public.culinary_places where slug='br'),true,'Wikimedia Commons — recette décrite par le photographe','https://commons.wikimedia.org/wiki/File:Feijoada.JPG','La description du fichier donne directement la composition : haricots noirs, laurier, ail, oignons, bouillon, bacon, porc et saucisses, avec environ deux heures de mijotage. La recette suit cette description et n’ajoute pas les accompagnements facultatifs mentionnés séparément.')
