insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,0,'Cuire les pommes de terre dans l’eau salée jusqu’à tendreté. Égoutter, ajouter le beurre et le persil, puis garder au chaud.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,1,'Aplatir les escalopes de veau très finement entre deux feuilles de papier cuisson. Saler et poivrer des deux côtés.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,2,'Préparer trois assiettes : farine, œufs battus et chapelure. Passer chaque escalope dans la farine, puis l’œuf, puis la chapelure sans la presser fortement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,3,'Chauffer suffisamment de beurre clarifié ou d’huile pour que l’escalope puisse presque flotter. La graisse doit grésiller immédiatement au contact de quelques miettes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,4,'Frire chaque schnitzel environ 2 à 3 minutes par côté jusqu’à coloration dorée, en faisant doucement bouger la poêle pour que la graisse passe sur la panure.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000023'::uuid,5,'Égoutter brièvement sur papier absorbant et servir immédiatement avec pommes de terre persillées et quartiers de citron.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,0,'Chauffer l’huile dans une large poêle à paella. Faire bien dorer les morceaux de poulet et de lapin de tous les côtés.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,1,'Ajouter haricots verts et artichauts, puis faire revenir quelques minutes. Ajouter la tomate râpée et laisser réduire.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,2,'Ajouter le paprika en remuant brièvement, puis verser l’eau. Ajouter safran, garrofó, sel et une branche de romarin.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,3,'Laisser bouillir environ 15 minutes pour former un bouillon goûteux. Ajouter les escargots.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,4,'Verser le riz en le répartissant uniformément dans toute la poêle. Ne plus remuer après cette étape.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,5,'Cuire d’abord à feu soutenu puis réduire progressivement jusqu’à absorption du liquide, environ 18 à 20 minutes. Ajouter la seconde branche de romarin vers la fin puis la retirer.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000024'::uuid,6,'Laisser reposer la paella 5 à 10 minutes hors du feu avant de servir directement dans le plat.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,0,'Mélanger la farine avec le dashi et l’igname râpé. Incorporer les œufs sans trop travailler la pâte.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,1,'Ajouter le chou émincé et mélanger juste assez pour bien l’enrober de pâte.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,2,'Chauffer une grande plaque ou poêle légèrement huilée. Former quatre galettes épaisses et rondes. Déposer les tranches de porc sur le dessus.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,3,'Cuire environ 5 à 6 minutes à feu moyen, retourner délicatement puis cuire encore 5 à 6 minutes jusqu’à ce que l’intérieur soit pris et le porc bien cuit.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,4,'Retourner une dernière fois côté chou vers le haut. Napper généreusement de sauce okonomiyaki puis tracer la mayonnaise par-dessus.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000025'::uuid,5,'Saupoudrer d’aonori et couvrir de flocons de katsuobushi. Servir immédiatement sur la plaque ou une assiette chaude.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,0,'Égoutter les haricots trempés. Les placer dans une grande marmite avec le bouillon, le laurier et suffisamment d’eau pour bien les couvrir.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,1,'Porter à frémissement et cuire environ 45 minutes avant d’ajouter les viandes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,2,'Dans une poêle, faire revenir le bacon, le porc et les saucisses jusqu’à ce qu’ils soient légèrement dorés. Ajouter oignons et ail et cuire jusqu’à tendreté.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,3,'Transférer tout le contenu de la poêle dans la marmite de haricots. Mélanger et laisser mijoter très doucement environ 1 heure 30 à 2 heures, jusqu’à ce que les haricots soient crémeux et les viandes tendres.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,4,'Ajouter un peu d’eau au besoin pendant la cuisson pour maintenir une consistance de ragoût épais.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000026'::uuid,5,'Goûter seulement à la fin avant d’ajouter sel et poivre, car bacon et saucisses apportent déjà beaucoup de sel. Servir la feijoada telle quelle pour correspondre à la photo choisie.',null,null);
